import { Glyph, GlyphType } from "../../enums";
import type { PropSymbol } from "../../models";
import { getGlyphUnicode } from "../../tokenizer";

/**
 * Creates a `PropSymbol` representing a propositional logic symbol.
 *
 * - If the character is a parenthesis, it is classified as `GlyphType.Parenthesis`.
 * - If the character is a known logical glyph, it is classified as `GlyphType.Operator`.
 * - If the character is a Latin letter, it is classified as `GlyphType.Variable`, and its view is the lowercase letter.
 * - Throws an error if the character is unrecognized.
 *
 * @param char - A single character representing a logical symbol.
 * @param position - The position of the symbol in the input expression.
 * @returns A `PropSymbol` containing the atom, type, position, and view.
 * @throws {Error} If the character is not a recognized logical symbol or a Latin letter.
 * @category Builders
 */
export function createPropSymbol(char: string, position: number): PropSymbol {
	const knownGlyphs = Object.values(Glyph);
	const onlyLatinLetters = /^[a-zA-Z]+$/;

	if (char === Glyph.OpenParenthesis || char === Glyph.CloseParenthesis) {
		return {
			position,
			atom: [char],
			type: GlyphType.Parenthesis,
			view: getGlyphUnicode(char),
		};
	} else if (knownGlyphs.includes(char as Glyph)) {
		return {
			position,
			atom: [char],
			type: GlyphType.Operator,
			view: getGlyphUnicode(char),
		};
	} else if (onlyLatinLetters.test(char)) {
		const firstLetter = char[0].toLowerCase();

		return {
			position,
			atom: [char],
			type: GlyphType.Variable,
			view: firstLetter,
		};
	} else {
		throw new Error(
			`Cannot create a propositional symbol from the character "${char}".`,
		);
	}
}

src/propositional/converters/convert-pro.source:
import { Operator } from "../../enums";
import type { PropExpression, PropFormula } from "../../models";
import { getOperatorGlyph } from "../../tokenizer";
import { createPropSymbol } from "../builders/create-prop-symbol";

/**
 * Converts a propositional formula into its corresponding expression representation.
 *
 * @param {PropFormula} formula - The propositional formula to convert.
 * @returns {PropExpression} The expression representation of the formula.
 * @category Converters
 */
export function convertPropFormulaToExpression(
	formula: PropFormula,
): PropExpression {
	const expression: PropExpression = [];
	let position = 0;

	function traverse(node: PropFormula): void {
		const { operator, values } = node;

		if (operator === Operator.Var) {
			expression.push(createPropSymbol(values[0] as string, position++));
			return;
		}

		expression.push(createPropSymbol("(", position++));

		if (operator === Operator.Not) {
			expression.push(createPropSymbol(getOperatorGlyph(operator), position++));
			traverse((values as PropFormula[])[0]);
		} else {
			const [left, right] = values as PropFormula[];
			traverse(left);
			expression.push(createPropSymbol(getOperatorGlyph(operator), position++));
			traverse(right);
		}

		expression.push(createPropSymbol(")", position++));
	}

	traverse(formula);
	return expression;
}

import { Operator } from "../../enums";
import type { PropFormula } from "../../models";
import { getGlyphUnicode, getOperatorGlyph } from "../../tokenizer";

/**
 * Converts a propositional formula into a string representation using Unicode logical symbols.
 *
 * @param {PropFormula} formula - The propositional formula to convert.
 * @returns {string} The string representation of the formula using Unicode glyphs.
 * @category Converters
 */
export function convertPropFormulaToString(formula: PropFormula): string {
	if (formula.operator === Operator.Var) {
		return formula.values[0] as string;
	}

	const glyph = getGlyphUnicode(getOperatorGlyph(formula.operator));
	const subFormulas = formula.values as PropFormula[];
	const values = subFormulas.map(convertPropFormulaToString);

	if (formula.operator === Operator.Not) {
		return `${glyph}${values[0]}`;
	}

	const glyphSpace = ` ${glyph} `;

	return `(${values.join(glyphSpace)})`;
}

