import { Operator } from "../../enums";
import type { PropFormula, PropFormulaVariablesMap } from "../../models";
import { extractPropVariables } from "../converters/extract-prop-variables";
import { getBinaryOperationValue } from "./get-binary-operation-value";
import { getUnaryOperationValue } from "./get-unary-operation-value";

/**
 * Evaluates a propositional formula based on a given truth assignment.
 *
 * @param {Object} params - Function parameters:
 * @param {PropFormula} params.formula - The propositional formula in tree-like structure.
 * @param {boolean[]} params.assignment - The truth assignment for the variables.
 * @param {variablesMap} [params.variablesMap] -  The map of formula variables ordered alphabetically
 * @returns {boolean} - The boolean result of the evaluated formula.
 * @throws {Error} If the number of variables in the formula does not match the assignment length.
 * @category Evaluators
 */
export function calculatePropFormula({
	formula,
	assignment,
	variablesMap,
}: {
	formula: PropFormula;
	assignment: boolean[];
	variablesMap?: PropFormulaVariablesMap;
}): boolean {
	const variables = variablesMap ?? extractPropVariables(formula);

	if (variables.size !== assignment.length) {
		throw new Error(
			`Mismatch between formula variables (${variables.size}) and assignment length (${assignment.length}).`,
		);
	}

	const variableValues = new Map<string, boolean>();

	variables.forEach((atom, index) => {
		variableValues.set(atom[0], assignment[index]);
	});

	function evaluate(node: PropFormula): boolean {
		if (node.operator === Operator.Var) {
			return !!variableValues.get(node.values[0] as string);
		}

		if (node.operator === Operator.Not) {
			const operand = node.values[0] as PropFormula;
			return getUnaryOperationValue({
				operator: node.operator,
				operand: evaluate(operand),
			});
		}

		const [left, right] = node.values as PropFormula[];
		return getBinaryOperationValue({
			operator: node.operator,
			leftOperand: evaluate(left),
			rightOperand: evaluate(right),
		});
	}

	return evaluate(formula);
}

src/propositional/evaluators/get-binary-.source:
import { Operator } from "../../enums";

/**
 * Evaluates the logical value of a binary operation given two boolean operands.
 *
 * @param {Object} params - Function parameters.
 * @param params.operator - The logical operator to apply.
 * @param params.leftOperand - The boolean value of the left operand.
 * @param params.rightOperand - The boolean value of the right operand.
 * @returns The result of applying the operator to the operands.
 * @throws {Error} If the operator is not a binary operator.
 * @category Evaluators
 */
export function getBinaryOperationValue({
	operator,
	leftOperand,
	rightOperand,
}: {
	operator: Operator;
	leftOperand: boolean;
	rightOperand: boolean;
}): boolean {
	switch (operator) {
		case Operator.And:
			return leftOperand && rightOperand;
		case Operator.Or:
			return leftOperand || rightOperand;
		case Operator.Implies:
			return !leftOperand || rightOperand;
		case Operator.ReversedImplies:
			return !rightOperand || leftOperand;
		case Operator.Equiv:
			return leftOperand === rightOperand;
		case Operator.Xor:
			return leftOperand !== rightOperand;
		case Operator.Nand:
			return !(leftOperand && rightOperand);
		case Operator.Nor:
			return !(leftOperand || rightOperand);
		case Operator.AntiImplies:
			return leftOperand && !rightOperand;
		case Operator.ReversedAntiImplies:
			return rightOperand && !leftOperand;
		case Operator.Contradiction:
			return false;
		case Operator.Tautology:
			return true;
		case Operator.Var:
		case Operator.Not:
			throw new Error(`Operator "${operator}" is not a binary operator.`);
		default:
			throw new Error(`Unknown operator: "${operator}".`);
	}
}

