import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";

/**
 * Constructs a formula based on the Implication Distribution axiom schema:
 * ((A => (B => C)) => ((A => B) => (A => C)))
 *
 * @param formulas - An array of propositional formulas.
 * @returns A new propositional formula representing the axiom schema.
 */
export function implicationDistributionSchema(
	formulas: PropFormula[],
): PropFormula {
	const [A, B, C] = formulas;

	return {
		operator: Operator.Implies,
		values: [
			{
				operator: Operator.Implies,
				values: [A, { operator: Operator.Implies, values: [B, C] }],
			},
			{
				operator: Operator.Implies,
				values: [
					{ operator: Operator.Implies, values: [A, B] },
					{ operator: Operator.Implies, values: [A, C] },
				],
			},
		],
	};
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";

/**
 * Generates a formula based on the Implication Introduction axiom schema.
 *
 * Given two formulas A and B, this function returns the formula:
 * (A => (B => A)).
 *
 * @param formulas - An array of propositional formulas.
 * @returns A new formula representing (A => (B => A)).
 */
export function implicationIntroductionSchema(
	formulas: PropFormula[],
): PropFormula {
	const [A, B] = formulas;

	return {
		operator: Operator.Implies,
		values: [
			A,
			{
				operator: Operator.Implies,
				values: [B, A],
			},
		],
	};
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";

/**
 * Constructs a formula based on the Implication Reversal axiom schema:
 * ((~A => ~B) => (B => A))
 *
 * @param formulas - An array of propositional formulas.
 * @returns A new propositional formula representing the implication reversal.
 */
export function implicationReversalSchema(
	formulas: PropFormula[],
): PropFormula {
	const [A, B] = formulas;

	return {
		operator: Operator.Implies,
		values: [
			{
				operator: Operator.Implies,
				values: [
					{ operator: Operator.Not, values: [A] },
					{ operator: Operator.Not, values: [B] },
				],
			},
			{
				operator: Operator.Implies,
				values: [B, A],
			},
		],
	};
}

import { implicationDistributionSchema } from "./implication-distribution";
import { implicationIntroductionSchema } from "./implication-introduction";
import { implicationReversalSchema } from "./implication-reversal";

/**
 * Namespace containing all axiom schemas in Hilbert-style calculus.
 * Axioms are fundamental logical truths that serve as starting points for proofs.
 *
 * Available axiom schemas:
 * - II: Implication Introduction
 * - ID: Implication Distribution
 * - IR: Implication Reversal
 *
 * Each axiom can be instantiated with specific propositions through substitution.
 *
 * @namespace
 * @category Hilbert Calculus
 */
export const HilbertAxioms = Object.freeze({
	II: implicationIntroductionSchema,
	ID: implicationDistributionSchema,
	IR: implicationReversalSchema,
});

