import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { isImplicationDistributionApplicable } from "../../validators/is-implication-distribution-applicable";

/**
 * Applies the rule of Implication Distribution.
 *
 * Given a formula of the form F => (G => H),
 * it derives the implication (F => G) => (F => H).
 *
 * This rule applies to each formula in the input array that satisfies the schema.
 *
 * @param formulas - An array of propositional formulas, each with form F => (G => H).
 * @returns An array of derived implications, each with form (F => G) => (F => H).
 * @throws {Error} if implication distribution is not applicable.
 */
export function implicationDistributionRule(
	formulas: PropFormula[],
): PropFormula[] {
	if (!isImplicationDistributionApplicable(formulas)) {
		throw new Error(
			"Implication distribution requires each formula to have the form F => (G => H).",
		);
	}

	return formulas.map((formula) => {
		// Extract F, G, H from the formula F => (G => H)
		const F = (formula.values as PropFormula[])[0];
		const consequent = (formula.values as PropFormula[])[1];
		const G = (consequent.values as PropFormula[])[0];
		const H = (consequent.values as PropFormula[])[1];

		// Create (F => G) => (F => H)
		return {
			operator: Operator.Implies,
			values: [
				{
					operator: Operator.Implies,
					values: [F, G],
				},
				{
					operator: Operator.Implies,
					values: [F, H],
				},
			],
		};
	});
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { arePropFormulasStructurallyEqual } from "../../validators/are-prop-formulas-structurally-equal";
import { isImplicationEliminationApplicable } from "../../validators/is-implication-elimination-applicable";

/**
 * Applies the rule of Implication Elimination (Modus Ponens).
 *
 * Given an implication (A => B) and its antecedent A,
 * it derives the consequent B.
 *
 * @param formulas - An array of propositional formulas.
 * @returns The consequent of the implication if the rule is applicable.
 * @throws {Error} if implication elimination is not applicable.
 */
export function implicationEliminationRule(
	formulas: PropFormula[],
): PropFormula[] {
	if (!isImplicationEliminationApplicable(formulas)) {
		throw new Error(
			"Implication elimination is not applicable to the given formulas.",
		);
	}

	const [formula1, formula2] = formulas;

	// Find the implication formula and its antecedent
	let implicationFormula: PropFormula | undefined;

	// Check if formula1 is an implication with formula2 as antecedent
	if (
		formula1.operator === Operator.Implies &&
		Array.isArray(formula1.values) &&
		formula1.values.length === 2 &&
		arePropFormulasStructurallyEqual([formula1.values[0], formula2])
	) {
		implicationFormula = formula1;
	}
	// Check if formula2 is an implication with formula1 as antecedent
	else if (
		formula2.operator === Operator.Implies &&
		Array.isArray(formula2.values) &&
		formula2.values.length === 2 &&
		arePropFormulasStructurallyEqual([formula2.values[0], formula1])
	) {
		implicationFormula = formula2;
	}

	// Return the consequent of the implication (second value in the array)
	return [implicationFormula?.values[1] as PropFormula];
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { isImplicationIntroductionApplicable } from "../../validators";

/**
 * Applies the rule of Implication Introduction.
 *
 * Given a proven formula F and an arbitrary formula G,
 * it derives the implication G => F.
 *
 * This rule allows the introduction of implications in Hilbert-style calculus,
 * enabling the creation of conditional statements from established facts.
 *
 * @param formulas - An array containing [provenFormula, newFormula].
 *                   - provenFormula: The formula that has been proven
 *                   - newFormula: The arbitrary formula to be the antecedent
 * @returns The implication (newFormula => provenFormula)
 * @throws {Error} if implication creation is not applicable.
 */
export function implicationIntroductionRule(
	formulas: PropFormula[],
): PropFormula[] {
	if (!isImplicationIntroductionApplicable(formulas)) {
		throw new Error(
			"Implication introduction requires exactly two formulas: the proven formula and the new antecedent formula.",
		);
	}

	const [provenFormula, newFormula] = formulas;

	return [
		{
			operator: Operator.Implies,
			values: [newFormula, provenFormula],
		},
	];
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { isImplicationReversalApplicable } from "../../validators/is-implication-reversal-applicable";

/**
 * Applies the rule of Implication Reversal.
 *
 * Given a formula of the form ¬F => ¬G,
 * it derives the implication G => F.
 *
 * This rule allows contraposition in Hilbert-style calculus,
 * enabling the derivation of equivalent implications with reversed arguments.
 *
 * @param formulas - An array of propositional formulas, each with form ¬F => ¬G.
 * @returns An array of derived implications, each with form G => F.
 * @throws {Error} if implication reversal is not applicable.
 */
export function implicationReversalRule(
	formulas: PropFormula[],
): PropFormula[] {
	if (!isImplicationReversalApplicable(formulas)) {
		throw new Error(
			"Implication reversal requires each formula to have the form ¬F => ¬G.",
		);
	}

	return formulas.map((formula) => {
		// Extract F and G from the formula ¬F => ¬G
		const antecedent = (formula.values as PropFormula[])[0];
		const consequent = (formula.values as PropFormula[])[1];

		const F = (antecedent.values as PropFormula[])[0];
		const G = (consequent.values as PropFormula[])[0];

		// Create G => F
		return {
			operator: Operator.Implies,
			values: [G, F],
		};
	});
}

import { implicationDistributionRule } from "./implication-distribution";
import { implicationEliminationRule } from "./implication-elimination";
import { implicationIntroductionRule } from "./implication-introduction";
import { implicationReversalRule } from "./implication-reversal";

/**
 * Namespace containing all inference rules in Hilbert-style calculus.
 * Rules are the mechanisms for deriving new formulas from existing ones.
 *
 * Available rules:
 * - IE: Implication Elimination (Modus Ponens)
 * - II: Implication Introduction
 * - ID: Implication Distribution
 * - IR: Implication Reversal
 *
 * Hilbert-style calculus uses a minimal set of rules, relying heavily on axiom schemas
 * for its deductive power.
 *
 * @namespace
 * @category Hilbert Calculus
 */
export const HilbertRules = Object.freeze({
	II: implicationIntroductionRule,
	ID: implicationDistributionRule,
	IE: implicationEliminationRule,
	IR: implicationReversalRule,
});

