import type { PropFormula } from "../../../models";
import { isConjunctionEliminationApplicable } from "../../validators";

/**
 * Applies Conjunction Elimination rule to an array of conjunction formulas.
 *
 * Given (A ∧ B), this rule allows us to infer A and B separately.
 *
 * @param formulas An array of conjunction formulas to eliminate.
 * @returns {PropFormula[]} An array of inferred formulas after applying conjunction elimination.
 * @throws {Error} if any formula is not a conjunction.
 */
export function conjunctionElimination(formulas: PropFormula[]): PropFormula[] {
	if (!isConjunctionEliminationApplicable(formulas)) {
		throw new Error(
			"Conjunction Elimination is not applicable for the given formulas.",
		);
	}

	return formulas.flatMap((formula) => {
		const conjunct1 = formula.values[0] as PropFormula;
		const conjunct2 = formula.values[1] as PropFormula;

		return [conjunct1, conjunct2];
	});
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { isConjunctionIntroductionApplicable } from "../../validators";

/**
 * Applies the conjunction introduction rule.
 *
 * Given two formulas A and B, it returns two conjunctions: (A ∧ B) and (B ∧ A)
 *
 * @param formulas An array of propositional formulas.
 * @returns {[PropFormula, PropFormula]} A tuple containing the two inferred formulas.
 * @throws {Error} if the formulas do not satisfy conjunction introduction conditions.
 */
export function conjunctionIntroduction(
	formulas: PropFormula[],
): [PropFormula, PropFormula] {
	if (!isConjunctionIntroductionApplicable(formulas)) {
		throw new Error(
			"Conjunction introduction is not applicable to the given formulas.",
		);
	}

	const conjunct1 = formulas[0];
	const conjunct2 = formulas[1];

	return [
		{
			operator: Operator.And,
			values: [conjunct1, conjunct2],
		},
		{
			operator: Operator.And,
			values: [conjunct2, conjunct1],
		},
	];
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { isDisjunctionEliminationApplicable } from "../../validators";

/**
 * Applies the disjunction elimination rule:
 * Given formulas (A ∨ B), (A => C), and (B => C), we can infer C.
 *
 * @param formulas An array of propositional formulas.
 * @returns {[PropFormula]} A tuple containing the inferred formula.
 * @throws {Error} if the formulas do not satisfy disjunction elimination conditions.
 */
export function disjunctionElimination(formulas: PropFormula[]): [PropFormula] {
	if (!isDisjunctionEliminationApplicable(formulas)) {
		throw new Error(
			"Disjunction elimination is not applicable to the given formulas.",
		);
	}

	// Extract the consequent from one of the implications
	const implication1 = formulas.find(
		(formula) => formula.operator === Operator.Implies,
	);

	return [implication1?.values[1] as PropFormula];
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { isDisjunctionIntroductionApplicable } from "../../validators";

/**
 * Applies the disjunction introduction rule.
 *
 * Given two formulas A and B, it returns two disjunctions: (A ∨ B) and (B ∨ A)
 *
 * @param formulas An array of propositional formulas.
 * @returns {[PropFormula, PropFormula]} A tuple containing the two inferred formulas.
 * @throws {Error} if the formulas do not satisfy disjunction introduction conditions.
 */
export function disjunctionIntroduction(
	formulas: PropFormula[],
): [PropFormula, PropFormula] {
	if (!isDisjunctionIntroductionApplicable(formulas)) {
		throw new Error(
			"Disjunction introduction is not applicable to the given formulas.",
		);
	}

	const disjunct1 = formulas[0];
	const disjunct2 = formulas[1];

	return [
		{ operator: Operator.Or, values: [disjunct1, disjunct2] },
		{ operator: Operator.Or, values: [disjunct2, disjunct1] },
	];
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { isEquivalenceEliminationApplicable } from "../../validators";

/**
 * Performs equivalence elimination on the given formulas.
 *
 * If A <=> B, then we derive (A => B) and (B => A).
 *
 * @param formulas An array of propositional formulas.
 * @returns {PropFormula[]} An array containing the inferred formulas.
 * @throws {Error} if the formulas are not all equivalences.
 */
export function equivalenceElimination(formulas: PropFormula[]): PropFormula[] {
	if (!isEquivalenceEliminationApplicable(formulas)) {
		throw new Error(
			"Equivalence elimination is not applicable. All formulas must be equivalences.",
		);
	}

	return formulas.flatMap((formula) => {
		const [A, B] = formula.values as PropFormula[];
		return [
			{ operator: Operator.Implies, values: [A, B] },
			{ operator: Operator.Implies, values: [B, A] },
		];
	});
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { isEquivalenceIntroductionApplicable } from "../../validators";

/**
 * Introduces an equivalence (A <=> B) given two implications (A => B) and (B => A).
 *
 * @param formulas An array of propositional formulas.
 * @returns {[PropFormula]} A tuple containing the inferred formula.
 * @throws {Error} if the input formulas do not satisfy the equivalence introduction conditions.
 */
export function equivalenceIntroduction(
	formulas: PropFormula[],
): [PropFormula] {
	if (!isEquivalenceIntroductionApplicable(formulas)) {
		throw new Error(
			"Equivalence introduction is not applicable to the given formulas.",
		);
	}

	const [implication1, implication2] = formulas;
	const firstAntecedent = implication1.values[0] as PropFormula;
	const secondAntecedent = implication2.values[0] as PropFormula;

	return [
		{
			operator: Operator.Equiv,
			values: [firstAntecedent, secondAntecedent],
		},
	];
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { isImplicationEliminationApplicable } from "../../validators";

/**
 * Applies the rule of Implication Elimination.
 *
 * Given an implication (A => B) and its antecedent A,
 * it derives the consequent B.
 *
 * @param formulas An array of propositional formulas.
 * @returns {[PropFormula]} A tuple containing the inferred formula.
 * @throws {Error} if implication elimination is not applicable.
 */
export function implicationElimination(formulas: PropFormula[]): [PropFormula] {
	if (!isImplicationEliminationApplicable(formulas)) {
		throw new Error(
			"Implication elimination is not applicable to the given formulas.",
		);
	}

	const implicationFormula = formulas.find(
		(f) => f.operator === Operator.Implies,
	);

	return [implicationFormula?.values[1] as PropFormula];
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { isImplicationIntroductionApplicable } from "../../validators";

/**
 * Applies the implication introduction rule.
 *
 * Given two formulas premise and conclusion, it returns their implication
 *
 * @param formulas An array of propositional formulas.
 * @returns {[PropFormula]} A tuple containing the inferred formula.
 * @throws {Error} if the formulas do not satisfy disjunction introduction conditions.
 */
export function implicationIntroduction(
	formulas: PropFormula[],
): [PropFormula] {
	if (!isImplicationIntroductionApplicable(formulas)) {
		throw new Error(
			"Implication introduction is not applicable to the given formulas.",
		);
	}

	const [premise, conclusion] = formulas;

	return [{ operator: Operator.Implies, values: [premise, conclusion] }];
}

import { conjunctionElimination } from "./conjunction-elimination";
import { conjunctionIntroduction } from "./conjunction-introduction";
import { disjunctionElimination } from "./disjunction-elimination";
import { disjunctionIntroduction } from "./disjunction-introduction";
import { equivalenceElimination } from "./equivalence-elimination";
import { equivalenceIntroduction } from "./equivalence-introduction";
import { implicationElimination } from "./implication-elimination";
import { implicationIntroduction } from "./implication-introduction";
import { negationElimination } from "./negation-elimination";
import { negationIntroduction } from "./negation-introduction";

/**
 * Namespace containing all Natural Deduction inference rules.
 * Provides a complete set of introduction and elimination rules for propositional logic.
 *
 * Introduction rules allow deriving new formulas:
 * - NI: Negation Introduction
 * - CI: Conjunction Introduction
 * - DI: Disjunction Introduction
 * - II: Implication Introduction
 * - EI: Equivalence Introduction
 *
 * Elimination rules extract information from formulas:
 * - NE: Negation Elimination
 * - CE: Conjunction Elimination
 * - DE: Disjunction Elimination
 * - IE: Implication Elimination
 * - EE: Equivalence Elimination
 *
 * @namespace
 * @category Natural Calculus
 */
export const NaturalRules = Object.freeze({
	// Introduction rules
	NI: negationIntroduction,
	CI: conjunctionIntroduction,
	DI: disjunctionIntroduction,
	II: implicationIntroduction,
	EI: equivalenceIntroduction,
	// Elimination rules
	NE: negationElimination,
	CE: conjunctionElimination,
	DE: disjunctionElimination,
	IE: implicationElimination,
	EE: equivalenceElimination,
});

import type { PropFormula } from "../../../models";
import { isNegationEliminationApplicable } from "../../validators";

/**
 * Applies negation elimination rule:
 * If ~(~A), then we can infer ~A.
 *
 * @param formulas An array of propositional formulas.
 * @returns {[PropFormula]} A tuple containing the inferred formula.
 * @throws {Error} if negation introduction rule is not applicable.
 */
export function negationElimination(formulas: PropFormula[]): [PropFormula] {
	if (!isNegationEliminationApplicable(formulas)) {
		throw new Error(
			"Negation elimination is not applicable to the given formulas.",
		);
	}

	const firstNegationFormula = formulas[0];
	const secondNegationFormula = firstNegationFormula.values[0] as PropFormula;

	return [secondNegationFormula.values[0] as PropFormula];
}

import { Operator } from "../../../enums";
import type { PropFormula } from "../../../models";
import { isNegationIntroductionApplicable } from "../../validators";

/**
 * Applies negation introduction rule:
 * If (A => B) and (A => ~B), then we can infer ~A.
 *
 * @param formulas - An array of propositional formulas.
 * @returns {[PropFormula]} A tuple containing the inferred formula.
 * @throws {Error} if negation introduction rule is not applicable.
 */
export function negationIntroduction(formulas: PropFormula[]): [PropFormula] {
	if (!isNegationIntroductionApplicable(formulas)) {
		throw new Error(
			"Negation introduction is not applicable to the given formulas.",
		);
	}

	// Extract antecedent from the input formulas (both must have the same antecedent)
	const antecedent = formulas[0].values[0] as PropFormula;

	return [
		{
			operator: Operator.Not,
			values: [antecedent],
		},
	];
}

