import type { PropFormula, TruthAssignmentsMap } from "../../models";
import { extractPropVariables } from "../converters/extract-prop-variables";
import { calculatePropFormula } from "../evaluators/calculate-prop-formula";
import { generateTruthAssignments } from "./generate-truth-assignments";

/**
 * Generates a truth table for the given propositional formula.
 *
 * @param {PropFormula} formula - The propositional formula.
 * @param {number} [limit=100] - The max number of variables in the formula.
 * @returns {TruthAssignmentsMap} - A map where keys are assignments, and values are truth values.
 * @throws {Error} If the formula has more variables than the limit allows.
 * @category Truth Tables
 */
export function generatePropTruthTable(
	formula: PropFormula,
	limit = 100,
): TruthAssignmentsMap {
	// Step 1: Extract variables from the formula
	const variablesMap = extractPropVariables(formula);
	const variableCount = variablesMap.size;

	// Step 2: Generate truth assignments
	const truthAssignments = generateTruthAssignments(variableCount, limit);

	// Step 3: Compute formula truth values
	const truthTable: TruthAssignmentsMap = new Map();

	truthAssignments.forEach((assignment, index) => {
		const formulaValue = calculatePropFormula({
			formula,
			assignment,
			variablesMap,
		});

		truthTable.set(index, [...assignment, formulaValue]);
	});

	return truthTable;
}

import type { TruthAssignmentsMap } from "../../models";

/**
 * Generates all possible truth assignments for a given number of variables.
 *
 * @param varCount - The number of boolean variables.
 * @param limit - The maximum allowed number of variables (default: 100).
 * @returns A map of truth assignments, indexed by binary count.
 * @throws {Error} If varCount exceeds the limit.
 * @category Truth Tables
 */
export function generateTruthAssignments(
	varCount: number,
	limit: number = 100,
): TruthAssignmentsMap {
	if (varCount > limit) {
		throw new Error(
			`Exceeded maximum variable limit (${limit}) for truth assignments.`,
		);
	}

	const numAssignments = 2 ** varCount;
	const assignments: TruthAssignmentsMap = new Map();

	for (let i = 0; i < numAssignments; i++) {
		const binaryValues = Array.from({ length: varCount }, (_, bit) =>
			Boolean(i & (1 << (varCount - bit - 1))),
		);
		assignments.set(i, binaryValues);
	}

	return assignments;
}

src/propositional/validators/validate-pr.source:
import { PropFormulaCheck } from "../../enums";
import type { PropFormula } from "../../models";
import { arePropFormulasStructurallyEqual } from "./are-prop-formulas-structurally-equal";
import { isConjunctionEliminationApplicable } from "./is-conjunction-elimination-applicable";
import { isConjunctionIntroductionApplicable } from "./is-conjunction-introduction-applicable";
import { isDisjunctionEliminationApplicable } from "./is-disjunction-elimination-applicable";
import { isDisjunctionIntroductionApplicable } from "./is-disjunction-introduction-applicable";
import { isEquivalenceEliminationApplicable } from "./is-equivalence-elimination-applicable";
import { isEquivalenceIntroductionApplicable } from "./is-equivalence-introduction-applicable";
import { isImplicationDistributionApplicable } from "./is-implication-distribution-applicable";
import { isImplicationEliminationApplicable } from "./is-implication-elimination-applicable";
import { isImplicationIntroductionApplicable } from "./is-implication-introduction-applicable";
import { isImplicationReversalApplicable } from "./is-implication-reversal-applicable";
import { isNegationEliminationApplicable } from "./is-negation-elimination-applicable";
import { isNegationIntroductionApplicable } from "./is-negation-introduction-applicable";

type PropFormulaCheckFunction = (formulas: PropFormula[]) => boolean;

const PROP_FORMULA_CHECKS: Record<PropFormulaCheck, PropFormulaCheckFunction> =
	{
		[PropFormulaCheck.areEqual]: arePropFormulasStructurallyEqual,
		// Elimination rules
		[PropFormulaCheck.isIE]: isImplicationEliminationApplicable,
		[PropFormulaCheck.isDE]: isDisjunctionEliminationApplicable,
		[PropFormulaCheck.isCE]: isConjunctionEliminationApplicable,
		[PropFormulaCheck.isEE]: isEquivalenceEliminationApplicable,
		[PropFormulaCheck.isNE]: isNegationEliminationApplicable,
		// Introduction rules
		[PropFormulaCheck.isDI]: isDisjunctionIntroductionApplicable,
		[PropFormulaCheck.isCI]: isConjunctionIntroductionApplicable,
		[PropFormulaCheck.isEI]: isEquivalenceIntroductionApplicable,
		[PropFormulaCheck.isNI]: isNegationIntroductionApplicable,
		[PropFormulaCheck.isII]: isImplicationIntroductionApplicable,
		// Other rules
		[PropFormulaCheck.isID]: isImplicationDistributionApplicable,
		[PropFormulaCheck.isIR]: isImplicationReversalApplicable,
	};

/**
 * Applies a series of propositional formula checks to an array of formulas.
 *
 * @param formulas - An array of propositional formulas to check.
 * @param checks - An array of check names to apply (defaults to all available checks).
 * @returns An object mapping each check name to its boolean result.
 * @category Validators
 */
export function validatePropFormulas(
	formulas: PropFormula[],
	checks: PropFormulaCheck[] = Object.keys(
		PropFormulaCheck,
	) as PropFormulaCheck[],
): Record<PropFormulaCheck, boolean> {
	return checks.reduce<Record<string, boolean>>((results, checkName) => {
		const checkFunction = PROP_FORMULA_CHECKS[checkName];
		results[checkName] = checkFunction ? checkFunction(formulas) : false;
		return results;
	}, {});
}

src/tokenizer/get-glyph-unicode.ts.source:
import { Glyph, GlyphUnicode } from "../enums";

const GlyphsDictionary: Record<Glyph, GlyphUnicode> = {
	[Glyph.Implication]: GlyphUnicode.Implication,
	[Glyph.ReversedImplication]: GlyphUnicode.ReversedImplication,
	[Glyph.Conjunction]: GlyphUnicode.Conjunction,
	[Glyph.Disjunction]: GlyphUnicode.Disjunction,
	[Glyph.Negation]: GlyphUnicode.Negation,
	[Glyph.Equivalence]: GlyphUnicode.Equivalence,
	[Glyph.ExclusiveConjunction]: GlyphUnicode.ExclusiveConjunction,
	[Glyph.ShefferStroke]: GlyphUnicode.ShefferStroke,
	[Glyph.WebbOperation]: GlyphUnicode.WebbOperation,
	[Glyph.AntiImplication]: GlyphUnicode.AntiImplication,
	[Glyph.ReversedAntiImplication]: GlyphUnicode.ReversedAntiImplication,
	[Glyph.Contradiction]: GlyphUnicode.Contradiction,
	[Glyph.Tautology]: GlyphUnicode.Tautology,
	[Glyph.OpenParenthesis]: GlyphUnicode.OpenParenthesis,
	[Glyph.CloseParenthesis]: GlyphUnicode.CloseParenthesis,
};

/**
 * Converts a given logical glyph character into its corresponding Unicode representation.
 *
 * @param char - A string representing a logical glyph (e.g., '=>', '&', '|', '~', etc.).
 * @returns The corresponding Unicode character from the `GlyphUnicode` enum.
 * @throws {Error} If the character is not a recognized {@link Glyph}.
 */
export function getGlyphUnicode(char: string): GlyphUnicode {
	if (char in GlyphsDictionary) {
		return GlyphsDictionary[char as Glyph];
	} else {
		throw new Error(`Cannot get a GlyphUnicode for the character "${char}".`);
	}
}

src/tokenizer/get-operator-glyph.ts.source:
import { Glyph, Operator } from "../enums";

/**
 * Converts a given Operator into its corresponding {@link Glyph}.
 *
 * @param {Operator} operator - The logical operator to convert.
 * @returns {Glyph} - The corresponding glyph.
 * @throws {Error} If the operator is not recognized.
 */
export function getOperatorGlyph(operator: Operator): Glyph {
	switch (operator) {
		case Operator.Not:
			return Glyph.Negation;
		case Operator.And:
			return Glyph.Conjunction;
		case Operator.Or:
			return Glyph.Disjunction;
		case Operator.Implies:
			return Glyph.Implication;
		case Operator.ReversedImplies:
			return Glyph.ReversedImplication;
		case Operator.Equiv:
			return Glyph.Equivalence;
		case Operator.Xor:
			return Glyph.ExclusiveConjunction;
		case Operator.Nand:
			return Glyph.ShefferStroke;
		case Operator.Nor:
			return Glyph.WebbOperation;
		case Operator.AntiImplies:
			return Glyph.AntiImplication;
		case Operator.ReversedAntiImplies:
			return Glyph.ReversedAntiImplication;
		case Operator.Contradiction:
			return Glyph.Contradiction;
		case Operator.Tautology:
			return Glyph.Tautology;
		default:
			throw new Error(`Cannot convert operator "${operator}" to a glyph.`);
	}
}

src/tokenizer/tokenize-string.ts.source:
import { Glyph } from "../enums";

/**
 * Tokenizes an input string into an array of known logical glyphs and variable names.
 *
 * - Recognizes logical glyphs defined in {@link Glyph}.
 * - Groups consecutive English letters into variables.
 * - Ignores spaces in the input.
 * - Throws an error if the input contains unsupported characters.
 *
 * @param input - The logical expression as a string.
 * @returns An array of tokens (glyphs and variables).
 * @throws {Error} If the input contains unsupported characters.
 */
export function tokenizeString(input: string): string[] {
	if (!input.length) return [];
	// Sort by length to match longest first
	const glyphs = Object.values(Glyph).sort((a, b) => b.length - a.length);
	// Escape special chars
	const glyphPattern = glyphs
		.map((g) => g.replaceAll(/[.*+?^${}()|[\]\\]/g, String.raw`\$&`))
		.join("|");
	// Variables: one or more English letters
	const variablePattern = "[a-zA-Z]+";
	const tokenizer = new RegExp(`(${glyphPattern})|(${variablePattern})`, "g");

	const tokens: string[] = [];
	let match: RegExpExecArray | null = tokenizer.exec(input);

	while (match !== null) {
		tokens.push(match[0]);
		match = tokenizer.exec(input);
	}

	if (!tokens.length || tokens.join("") !== input.replaceAll(/\s+/g, "")) {
		throw new Error(`Invalid character(s) found in input: "${input}".`);
	}

	return tokens;
}

src/propositional/converters/extract-pro.source:
import { Operator } from "../../enums";
import type { PropFormula } from "../../models";

/**
 * Extracts all true sub-formulas from a given propositional formula.
 * This function does not include atomic formulas (Operator.Var) as sub-formulas,
 * nor does it include the input formula itself.
 *
 * @param {PropFormula} formula - The propositional formula to extract sub-formulas from.
 * @returns {PropFormula[]} An array of unique sub-formulas, sorted in evaluation order.
 * @category Converters
 */
export function extractPropSubFormulas(formula: PropFormula): PropFormula[] {
	if (formula.operator === Operator.Var) return [];

	const subFormulas = new Set<string>();
	const result: PropFormula[] = [];

	function traverse(subFormula: PropFormula): void {
		if (subFormula.operator === Operator.Var) {
			return;
		}

		const key = JSON.stringify(subFormula);
		if (!subFormulas.has(key)) {
			subFormulas.add(key);
			result.push(subFormula);
		}

		if (Array.isArray(subFormula.values)) {
			for (const value of subFormula.values) {
				traverse(value as PropFormula);
			}
		}
	}

	if (Array.isArray(formula.values)) {
		for (const value of formula.values) {
			traverse(value as PropFormula);
		}
	}

	return result;
}

import { Operator } from "../../enums";
import type { PropFormula, PropFormulaVariablesMap } from "../../models";

/**
 * Extracts all propositional variables from a given formula and returns them in a sorted map.
 *
 * @param formula - The propositional formula.
 * @returns A map of variables, sorted alphabetically.
 * @category Converters
 */
export function extractPropVariables(
	formula: PropFormula,
): PropFormulaVariablesMap {
	const variablesSet: Set<string> = new Set();

	function traverse(node: PropFormula): void {
		if (node.operator === Operator.Var) {
			variablesSet.add(node.values[0] as string); // Extract variable name
			return;
		}

		if (Array.isArray(node.values)) {
			const subFormulas = node.values as PropFormula[];
			for (const subFormula of subFormulas) {
				traverse(subFormula);
			}
		}
	}

	traverse(formula);

	const sortedVariables = Array.from(variablesSet).sort((a, b) =>
		a.localeCompare(b),
	);

	return new Map(sortedVariables.map((varName, index) => [index, [varName]]));
}

src/propositional/hilbert-calculus/class.source:
import type {
	HilbertAxiomPayload,
	HilbertDerivedPayload,
	PropAtom,
	PropFormula,
} from "../../../models";
import { HilbertProof } from "./hilbert-proof";

/**
 * A builder class for constructing Hilbert-style proofs.
 * Provides a chainable API for adding proof steps.
 *
 * @example
 * ```typescript
 * const proof = new HilbertProofBuilder(implicationAB)
 *	.addPremise(A, "First premise")
 *	.addPremise(B, "Second premise")
 *	.build();
 * ```
 *
 * @category Hilbert Calculus
 */
export class HilbertProofBuilder {
	private readonly proof: HilbertProof;

	/**
	 * Creates a new proof builder with a goal formula.
	 * @param goal - The target formula to prove
	 */
	constructor(goal: PropFormula) {
		this.proof = new HilbertProof(goal);
	}

	/**
	 * Adds a premise (given assumption) to the proof.
	 * @param formula - The premise formula
	 * @param comment - Optional explanation for the premise
	 * @returns This builder instance for chaining
	 */
	addPremise(formula: PropFormula, comment?: string): this {
		this.proof.addPremise(formula, comment);
		return this;
	}

	/**
	 * Adds an axiom step to the proof.
	 * @param payload - The axiom payload containing formulas and schema
	 * @param comment - Optional explanation for the axiom
	 * @returns This builder instance for chaining
	 */
	addAxiom(payload: HilbertAxiomPayload, comment?: string): this {
		this.proof.addAxiom(payload, comment);
		return this;
	}

	/**
	 * Adds a derived step to the proof using a Hilbert calculus rule.
	 * @param payload - The derived step payload containing formulas, schema, and step references
	 * @param comment - Optional explanation for the derivation
	 * @returns This builder instance for chaining
	 */
	addDerivedStep(payload: HilbertDerivedPayload, comment?: string): this {
		this.proof.addDerivedStep(payload, comment);
		return this;
	}

	/**
	 * Reiterates (repeats) a previously proved step.
	 * Allows referring to a formula from an earlier step in the proof.
	 * @param fromIndex - The index of the step to reiterate (1-based)
	 * @param comment - Optional explanation for the reiteration
	 * @returns This builder instance for chaining
	 */
	reiterateStep(fromIndex: number, comment?: string): this {
		this.proof.reiterateStep(fromIndex, comment);
		return this;
	}

	/**
	 * Replaces all occurrences of an atom with a formula or atom in all proof steps.
	 * The goal formula is not modified.
	 *
	 * @param atom - The atomic proposition to replace
	 * @param substitute - The formula or atom to substitute
	 * @returns This builder instance for chaining
	 */
	replace(atom: PropAtom, substitute: PropFormula | PropAtom): this {
		this.proof.replace(atom, substitute);
		return this;
	}

	/**
	 * Constructs the proof and returns it.
	 * @returns The completed HilbertProof instance
	 */
	build(): HilbertProof {
		return this.proof;
	}

	/**
	 * Adds multiple steps in sequence using a callback function.
	 * Useful for building complex proofs programmatically.
	 *
	 * @param stepsFn - A callback that receives the current builder and adds steps
	 * @returns This builder instance for chaining
	 *
	 * @example
	 * ```typescript
	 * proof.buildSteps((builder) => {
	 *   builder.addPremise(p);
	 *   builder.addAxiom(axiom1);
	 *   builder.addDerivedStep(derived1);
	 * });
	 * ```
	 */
	buildSteps(stepsFn: (builder: this) => void): this {
		stepsFn(this);
		return this;
	}

	/**
	 * Gets the current state of the proof without building.
	 * Useful for inspection during construction.
	 * @returns The current HilbertProof instance
	 */
	preview(): HilbertProof {
		return this.proof;
	}
}

