export function composeNaturalProof(
	goal: PropFormula,
	...stepGenerators: Array<(builder: NaturalProofBuilder) => void>
): NaturalProof {
	const builder = buildNaturalProof(goal);
	for (const generator of stepGenerators) {
		generator(builder);
	}
	return builder.build();
}

