import { Operator } from "../../enums";
import type { PropFormula } from "../../models";

/**
 * Checks if conjunction elimination is applicable.
 *
 * Conjunction elimination allows us to infer any conjunct from a conjunction.
 * This function verifies whether all provided formulas are conjunctions.
 *
 * @param formulas - An array of propositional formulas to check.
 * @returns `true` if all formulas are conjunctions, otherwise `false`.
 * @category Validators
 */
export function isConjunctionEliminationApplicable(
	formulas: PropFormula[],
): boolean {
	if (formulas.length === 0) {
		return false;
	}

	return formulas.every((formula) => formula.operator === Operator.And);
}

import type { PropFormula } from "../../models";

/**
 * Checks if conjunction introduction rule is applicable.
 *
 * Conjunction introduction allows us to infer a conjunction from any two conjuncts.
 *
 * @param formulas - An array of propositional formulas to check.
 * @returns `true` if all there are exactly two formulas in the array, otherwise `false`.
 * @category Validators
 */
export function isConjunctionIntroductionApplicable(
	formulas: PropFormula[],
): boolean {
	return formulas.length === 2;
}

