import { Operator } from "../../enums";
import type { PropFormula } from "../../models";

/**
 * Checks if implication distribution is applicable to a formula.
 *
 * A formula satisfies the implication distribution schema if it has the form:
 * F => (G => H), where F, G, and H are arbitrary propositional formulas.
 *
 * @param formula - The propositional formula to check.
 * @returns True if the formula matches the schema F => (G => H), false otherwise.
 * @category Validators
 */
function isImplicationDistributionSchema(formula: PropFormula): boolean {
	// Check if formula is F => (G => H)
	// The outer operator must be an implication
	if (formula.operator !== Operator.Implies) {
		return false;
	}

	// The values must be an array with exactly 2 elements
	if (!Array.isArray(formula.values) || formula.values.length !== 2) {
		return false;
	}

	// The second element (consequent) must be an implication (G => H)
	const consequent = formula.values[1];
	if (
		!Array.isArray(consequent.values) ||
		consequent.operator !== Operator.Implies ||
		consequent.values.length !== 2
	) {
		return false;
	}

	return true;
}

/**
 * Checks if implication distribution is applicable to all formulas in the array.
 *
 * Each formula in the input array must satisfy the schema F => (G => H).
 * If all formulas match the schema, distribution can be applied to each.
 *
 * @param formulas - An array of propositional formulas to check.
 * @returns True if all formulas match the distribution schema, false otherwise.
 * @category Validators
 */
export function isImplicationDistributionApplicable(
	formulas: PropFormula[],
): boolean {
	// At least one formula is required
	if (formulas.length === 0) {
		return false;
	}

	// All formulas must satisfy the implication distribution schema
	return formulas.every(isImplicationDistributionSchema);
}

import { Operator } from "../../enums";
import type { PropFormula } from "../../models";
import { arePropFormulasStructurallyEqual } from "./are-prop-formulas-structurally-equal";

/**
 * Checks if implication elimination (modus ponens) is applicable to two given formulas.
 *
 * This function verifies that:
 * - Exactly two formulas in the input array
 * - One of the formulas is an implication.
 * - The other formula is structurally equal to the antecedent of the implication.
 *
 * @param formulas - An array of propositional formulas to check.
 * @returns True if implication elimination can be applied, false otherwise.
 * @category Validators
 */
export function isImplicationEliminationApplicable(
	formulas: PropFormula[],
): boolean {
	if (formulas.length !== 2) return false;
	const [formula1, formula2] = formulas;

	const checkImplication = (
		implication: PropFormula,
		antecedent: PropFormula,
	) =>
		implication.operator === Operator.Implies &&
		Array.isArray(implication.values) &&
		implication.values.length === 2 &&
		arePropFormulasStructurallyEqual([implication.values[0], antecedent]);

	return (
		checkImplication(formula1, formula2) || checkImplication(formula2, formula1)
	);
}

import type { PropFormula } from "../../models";

/**
 * Checks if implication creation is applicable.
 *
 * This function verifies that:
 * - Exactly two formulas are provided
 * - Both formulas are well-formed (minimal check)
 *
 * Implication creation allows deriving G => F from any proven formula F
 * with any arbitrary formula G.
 *
 * @param formulas - An array of propositional formulas to check.
 * @returns True if implication creation can be applied, false otherwise.
 * @category Validators
 */
export function isImplicationIntroductionApplicable(
	formulas: PropFormula[],
): boolean {
	return formulas.length === 2;
}

import { Operator } from "../../enums";
import type { PropFormula } from "../../models";

/**
 * Checks if implication reversal is applicable to a formula.
 *
 * A formula satisfies the implication reversal schema if it has the form:
 * ¬F => ¬G, where F and G are arbitrary propositional formulas.
 *
 * @param formula - The propositional formula to check.
 * @returns True if the formula matches the schema ¬F => ¬G, false otherwise.
 * @category Validators
 */
function isImplicationReversalSchema(formula: PropFormula): boolean {
	// Check if formula is ¬F => ¬G
	// The outer operator must be an implication
	if (formula.operator !== Operator.Implies) {
		return false;
	}

	// The values must be an array with exactly 2 elements
	if (!Array.isArray(formula.values) || formula.values.length !== 2) {
		return false;
	}

	const antecedent = formula.values[0];
	const consequent = formula.values[1];

	// Both antecedent and consequent must be negations (¬F and ¬G)
	if (
		!Array.isArray(antecedent.values) ||
		antecedent.operator !== Operator.Not ||
		antecedent.values.length !== 1
	) {
		return false;
	}

	if (
		!Array.isArray(consequent.values) ||
		consequent.operator !== Operator.Not ||
		consequent.values.length !== 1
	) {
		return false;
	}

	return true;
}

/**
 * Checks if implication reversal is applicable to all formulas in the array.
 *
 * Each formula in the input array must satisfy the schema ¬F => ¬G.
 * If all formulas match the schema, reversal can be applied to each.
 *
 * @param formulas - An array of propositional formulas to check.
 * @returns True if all formulas match the reversal schema, false otherwise.
 * @category Validators
 */
export function isImplicationReversalApplicable(
	formulas: PropFormula[],
): boolean {
	// At least one formula is required
	if (formulas.length === 0) {
		return false;
	}

	// All formulas must satisfy the implication reversal schema
	return formulas.every(isImplicationReversalSchema);
}

src/propositional/validators/is-negation.source:
import { Operator } from "../../enums";
import type { PropFormula } from "../../models";

/**
 * Checks if negation elimination is applicable to all given formulas.
 *
 * Negation elimination states that if we have a double negation, we can remove it.
 * This function verifies whether each formula in the array has exactly two negations at the top level.
 *
 * @param formulas - An array of propositional formulas to check.
 * @returns `true` if all formulas contain exactly two negations, otherwise `false`.
 * @category Validators
 */
export function isNegationEliminationApplicable(
	formulas: PropFormula[],
): boolean {
	if (formulas.length === 0) {
		return false;
	}

	return formulas.every(
		(formula) =>
			formula.operator === Operator.Not &&
			Array.isArray(formula.values) &&
			formula.values.length === 1 &&
			(formula.values[0] as PropFormula).operator === Operator.Not,
	);
}

import { Operator } from "../../enums";
import type { PropFormula } from "../../models";
import { arePropFormulasStructurallyEqual } from "./are-prop-formulas-structurally-equal";

/**
 * Checks if negation introduction is applicable.
 *
 * Negation introduction allows us to infer ¬A from two implications:
 *  1) A → B
 *  2) A → ¬B
 *
 * @param formulas - An array of propositional formulas to check.
 * @returns `true` if we can infer negation, otherwise `false`.
 * @category Validators
 */
export function isNegationIntroductionApplicable(
	formulas: PropFormula[],
): boolean {
	if (formulas.length !== 2) {
		return false;
	}

	const [formula1, formula2] = formulas;

	if (
		formula1.operator !== Operator.Implies ||
		formula2.operator !== Operator.Implies
	) {
		return false;
	}

	const [antecedent1, consequent1] = formula1.values as PropFormula[];
	const [antecedent2, consequent2] = formula2.values as PropFormula[];

	if (!arePropFormulasStructurallyEqual([antecedent1, antecedent2])) {
		return false;
	}

	return (
		(consequent1.operator === Operator.Not &&
			arePropFormulasStructurallyEqual([
				consequent1.values[0] as PropFormula,
				consequent2,
			])) ||
		(consequent2.operator === Operator.Not &&
			arePropFormulasStructurallyEqual([
				consequent2.values[0] as PropFormula,
				consequent1,
			]))
	);
}

src/propositional/validators/is-well-for.source:
import { Glyph, GlyphType } from "../../enums";
import type { PropExpression, PropSymbol } from "../../models";

/**
 * Checks whether a given propositional expression is a well-formed formula (WFF).
 *
 * A WFF follows these rules:
 * 1) Any single variable itself is a WFF.
 * 2) Any WFF can be prefixed with "~" to form another WFF.
 * 3) Any two WFFs can be combined with "&", "|", "=>", or "<=>" inside parentheses to form another WFF.
 *
 * Parentheses are mandatory when joining two WFFs using binary operators.
 *
 * @param expression - The propositional expression as an array of PropSymbols.
 * @returns `true` if the expression is a valid WFF, otherwise `false`.
 * @category Validators
 */
export function isWellFormedFormula(expression: PropExpression): boolean {
	if (expression.length === 0) return false;

	let index = 0;

	function parseWFF(): boolean {
		if (isEndOfExpression()) return false;

		if (isVariable(expression[index])) {
			return parseVariable();
		}

		if (isNegation(expression[index])) {
			return parseNegation();
		}

		if (isParenthesizedExpression(expression[index])) {
			return parseParenthesizedExpression();
		}

		return false;
	}

	function parseVariable(): boolean {
		index++; // A single variable is a WFF
		return true;
	}

	function parseNegation(): boolean {
		index++; // Consume "~"
		return parseWFF(); // Negation must be followed by a valid WFF
	}

	function parseParenthesizedExpression(): boolean {
		index++; // Consume "("

		if (!parseWFF()) return false; // First WFF must exist

		if (isEndOfExpression() || !isBinaryOperator(expression[index]))
			return false;
		index++; // Consume operator

		if (!parseWFF()) return false; // Second WFF must exist

		if (isEndOfExpression() || !isClosingParenthesis(expression[index]))
			return false;
		index++; // Consume ")"

		return true;
	}

	function isEndOfExpression(): boolean {
		return index >= expression.length;
	}

	const result = parseWFF();
	return result && index === expression.length; // Ensure full expression is parsed
}

function isVariable(symbol: PropSymbol): boolean {
	return symbol.type === GlyphType.Variable;
}

function isNegation(symbol: PropSymbol): boolean {
	return symbol.atom[0] === Glyph.Negation;
}

function isParenthesizedExpression(symbol: PropSymbol): boolean {
	return symbol.atom[0] === Glyph.OpenParenthesis;
}

function isBinaryOperator(symbol: PropSymbol): boolean {
	return (
		symbol.type === GlyphType.Operator && symbol.atom[0] !== Glyph.Negation
	);
}

function isClosingParenthesis(symbol: PropSymbol): boolean {
	return symbol.atom[0] === Glyph.CloseParenthesis;
}

